            @Confirm.canceled += instance.OnConfirm;
            @Cancell.started += instance.OnCancell;
            @Cancell.performed += instance.OnCancell;
            @Cancell.canceled += instance.OnCancell;
            @EquipmentScreen.started += instance.OnEquipmentScreen;
            @EquipmentScreen.performed += instance.OnEquipmentScreen;
            @EquipmentScreen.canceled += instance.OnEquipmentScreen;
        }

        /// <summary>
        /// Removes <see cref="InputAction.started"/>, <see cref="InputAction.performed"/> and <see cref="InputAction.canceled"/> callbacks provided via <param cref="instance" /> on all input actions contained in this map.
        /// </summary>
        /// <remarks>
        /// Calling this method when <paramref name="instance" /> have not previously been registered has no side-effects.
        /// </remarks>
        /// <seealso cref="WorldHubActions" />
        private void UnregisterCallbacks(IWorldHubActions instance)
        {
            @Movement.started -= instance.OnMovement;
            @Movement.performed -= instance.OnMovement;
            @Movement.canceled -= instance.OnMovement;
            @Confirm.started -= instance.OnConfirm;
            @Confirm.performed -= instance.OnConfirm;
            @Confirm.canceled -= instance.OnConfirm;
            @Cancell.started -= instance.OnCancell;
            @Cancell.performed -= instance.OnCancell;
            @Cancell.canceled -= instance.OnCancell;
            @EquipmentScreen.started -= instance.OnEquipmentScreen;
            @EquipmentScreen.performed -= instance.OnEquipmentScreen;
            @EquipmentScreen.canceled -= instance.OnEquipmentScreen;
        }

        /// <summary>
        /// Unregisters <param cref="instance" /> and unregisters all input action callbacks via <see cref="WorldHubActions.UnregisterCallbacks(IWorldHubActions)" />.
        /// </summary>
        /// <seealso cref="WorldHubActions.UnregisterCallbacks(IWorldHubActions)" />
        public void RemoveCallbacks(IWorldHubActions instance)
        {
            if (m_Wrapper.m_WorldHubActionsCallbackInterfaces.Remove(instance))
                UnregisterCallbacks(instance);
        }

        /// <summary>
        /// Replaces all existing callback instances and previously registered input action callbacks associated with them with callbacks provided via <param cref="instance" />.
        /// </summary>
        /// <remarks>
        /// If <paramref name="instance" /> is <c>null</c>, calling this method will only unregister all existing callbacks but not register any new callbacks.
        /// </remarks>
        /// <seealso cref="WorldHubActions.AddCallbacks(IWorldHubActions)" />
        /// <seealso cref="WorldHubActions.RemoveCallbacks(IWorldHubActions)" />
        /// <seealso cref="WorldHubActions.UnregisterCallbacks(IWorldHubActions)" />
        public void SetCallbacks(IWorldHubActions instance)
        {
            foreach (var item in m_Wrapper.m_WorldHubActionsCallbackInterfaces)
                UnregisterCallbacks(item);
            m_Wrapper.m_WorldHubActionsCallbackInterfaces.Clear();
            AddCallbacks(instance);
        }
    }
